INSERT INTO `mod_lore_codex_entry` (`ID`, `Kind`, `Zone`, `SortOrder`, `Faction`, `RequiredState`, `Title`, `Body`, `Sources`) VALUES
(351800, 0, 3518, 0, 0, 0, 'Nagrand', 'Nagrand is one of the few green lands left on shattered Draenor. While the rest of the world was scorched by fel magic or torn apart, these rolling grasslands survived largely untouched, and great islands of earth still drift above the plains, spilling waterfalls into the lakes below. For the orcs, Oshu''gun, the diamond mountain in the southwest, was once the heart of their faith: the clans gathered beneath it each spring, and their shaman spoke there with the ancestors. Now the land is crowded with peoples and dangers. The Mag''har, orcs who never drank the demon''s blood, hold Garadar in the north, while the Kurenai, Broken draenei who seek redemption, have reclaimed Telaar in the south. Between them the abandoned draenei city of Halaa changes hands in open war. Warmaul and Boulderfist ogres fight over the hills, the Shadow Council lurks at Kil''sorrow Fortress, the Burning Legion builds forge camps in the west, and at the Throne of the Elements the Earthen Ring struggles to calm the restless spirits of the land.', 'warcraft.wiki.gg/wiki/Nagrand (sacred to the orcs, uncorrupted, last unscarred region, floating lake islands, Mag''har and Kurenai, Halaa contested); quest 10101 description (Oshu''gun, clans gathered, shaman communed with ancestors); quests 9890, 9946 (Boulderfist and Warmaul); quest 9935 (Kil''sorrow, communing with the Legion); quest 9999 (forge camps); quest 9804 (Earthen Ring, restless waters); warcraft.wiki.gg/wiki/Kurenai (redeemed Broken, Telaar); quest 9921 completion text (Telaar only recently taken back)'),
(351801, 1, 3518, 1, 0, 0, 'Garadar', 'Garadar, the home of the Mag''har, stands in northern Nagrand. Its people call themselves survivors of the red pox and of a shattered world, and because they were set apart from the rest of their race, they never shared the corruption that turned other orcs green. Today Garadar is a town under strain. Refugees from Sunspring Post and the Bleeding Hollow village crowd its streets with orphaned children, the matrons struggle to feed them, and the Greatmother lies ill in her hospice while young Garrosh broods by the fire. Captain Kroghan, a Horde officer sent only to pass through, has chosen to stay on as the Horde''s liaison to the town.', 'warcraft.wiki.gg/wiki/Garadar (red pox quarantine, named for Garad, Mag''har avoided corruption, Geyah''s hospice, Kroghan); creature_text 18489 (Grandson of Garad and Geyah); DB spawns in area 3613: Sunspring Post Refugee/Orphan, Bleeding Hollow Refugee/Orphan, Captain Kroghan 18090; quest 9916 description (burden on the matrons of Garadar); npc_text 9271 (Kurkush: Greatmother ill, Garrosh depressed); quest 9797 reward text (Kroghan); npc_text 9289 (Jorin: survivors of the Red Pox and of a shattered world); quest 11048 description (Kroghan stays as long term Horde liaison); warcraft.wiki.gg/wiki/Garad (Rise of the Horde has Garad killed by ogres; the quarantine and naming story cites Chronicle 2 and The Shattering)'),
(351802, 1, 3518, 2, 0, 0, 'Telaar', 'In the far south of Nagrand lies Telaar, one of the very few draenei towns on Draenor whose graceful architecture survived intact. It is home now to the Kurenai, a tribe of Broken who escaped their slavers and work to overcome their demonic taint; their name means redeemed. They took the town back only recently and mean to keep it. Arechron leads them, with Mo''mor the Breaker, Otonbu the Sage and Poli''lukluk the Wiser at his side. They have welcomed the Alliance their draenei kin have joined. In the town''s jail, blood elves captured at Halaa await questioning, and the old hatred between the Broken and the orcs is never far from anyone''s mind.', 'warcraft.wiki.gg/wiki/Telaar (intact draenei architecture, Kurenai town, Arechron); warcraft.wiki.gg/wiki/Kurenai (escaped slavers, overcoming taint, name means redeemed, support draenei joining the Alliance); quest 9921 completion text (only recently taken back Telaar); DB spawns area 3626: Mo''mor 18223, Otonbu 18222, Poli''lukluk 18224, Elementalist Ioki, Shotgun Jones, Consortium, Captured Halaani Blood Knight 19151, Interrogator Khan; npc_text 9738 (Telaari Jailor: blood elves questioned); quest 11502 description (history of bloodshed and betrayal with the orcs)'),
(351803, 1, 3518, 3, 0, 0, 'Halaa', 'On a plateau in the heart of Nagrand stand the empty halls of Halaa, once the foremost draenei research site for the study of naaru crystals. Its builders are long gone, but their notes on the crystals of Oshu''gun remain, and powder from the diamond mountain is found in the earth all across the region. That prize has drawn the Alliance and the Horde into open war. Draenei and blood elves fight over the town street by street, and whichever side holds it brings in researchers to gather the crystal powder, quartermasters to reward their soldiers, and guards to defend the walls until the next assault. Rarely does a banner fly over Halaa for long.', 'quest 10074/10076 description (primary draenei research facility for naaru crystals, Oshu''gun powder in the region); quest 9815 description (abandoned city of Halaa); warcraft.wiki.gg/wiki/Halaa (contested town, guards, researchers and quartermasters of the holding side); npc_text 9738 and 9739 (blood elves and draenei fighting at Halaa, after crystal powder); quest 9864 description (Halaa is a war-zone)'),
(351804, 1, 3518, 4, 0, 0, 'Halaani Basin and the Twin Clefts', 'Below the plateau of Halaa spreads the Halaani Basin, a wide hollow where Nagrand''s troubled waters gather. Spawns of muck crawl through its pools, and the Earthen Ring warns that each leaves tainted debris that will spread unless carried away. Raging crushers of poisoned rock roam the basin as well. Within it lie the twin clefts, Northwind and Southwind, where Boulderfist shock troops have hidden their ogre mounds. The ogres stacked supplies stolen from the Bleeding Hollow village in the clefts, and when young Corki of Telaar went looking for trouble, it was here that the Boulderfist caught and caged him.', 'quest 9815 description (muck spawns beneath Halaa, tainted debris); quest 9821 reward text (crusher rocks are poison); DB spawns 3666: Muck Spawn, Enraged Crusher; quests 9907, 9922 descriptions (twin clefts Northwind and Southwind, Boulderfist mounds); quest 9916 description (stolen supplies in the clefts); quest 9924 description and Corki 20812 at Northwind Cleft'),
(351805, 1, 3518, 5, 0, 0, 'The Throne of the Elements', 'In the northern hills beyond Skysong Lake rises the Throne of the Elements, a sacred place where the spirits of Nagrand are honored. The four furies dwell there in person: Gordawg of earth, Incineratus of fire, Aborius of water and Kalandrios of air. Shaman of the Earthen Ring keep the site, among them Elementalist Sharvak, who fears for a world whose people fight on while the elements themselves are in turmoil. Some of her companions are Broken, such as Morgh and Lo''ap, who grieve that their own kin are among those corrupting the land. Envoys of the Ring travel to both Garadar and Telaar to report on the state of the elements.', 'DB spawns 3615: Gordawg 18099 Fury of Earth, Incineratus 18100, Aborius 18101 Fury of Water, Kalandrios 18102, Elementalists Untrag, Sharvak, Lo''ap, Morgh; quests 9869, 9870 descriptions (northern hills beyond Skysong Lake, envoys to Telaar and Garadar); npc_text 9182 (Sharvak); quest 9862 description (Morgh: Murkblood are my kin); quest 9805 completion text (Lo''ap: my own kin); warcraft.wiki.gg/wiki/Throne_of_the_Elements (furies and Earthen Ring)'),
(351806, 1, 3518, 6, 0, 0, 'Skysong Lake', 'Skysong Lake lies just below the Throne of the Elements, and its waters are in turmoil. A disturbance in the ebb and flow of the region''s waters has driven the lake spirits into a frenzy, and they have begun to wreak havoc through the waterways. The shaman of the Throne say that Watoosun of the Water came to them in a vision and allowed them to put the maddened spirits down, on the condition that the cause of the trouble also be found. Talbuk graze along its shores, and the great crocolisk Goretooth hunts the lakes of Nagrand.', 'quest 9804 description (disturbance, agitated water spirits of Skysong Lake, Watoosun vision and condition); DB spawns 3614: Lake Spirit 17153, Talbuk Thorngrazer, Goretooth 17144 (rare, also spawns at Lake Sunspring and Halaani Basin); quest 9869 description (Throne beyond Skysong Lake); creature_template 17144 (family 6, crocolisk; rank 4 rare)'),
(351807, 1, 3518, 7, 0, 0, 'Windyreed Village', 'Windyreed Village, a cluster of huts southeast of the Throne of the Elements, is one source of the sickness in the land''s lakes. Its people are Lost Ones, draenei who have fallen even further than the Broken, once banished to the swamps of Zangarmarsh. Now they seek to spread their filth beyond the marsh, dredging up the waters of Nagrand to turn them into swamp, and the Broken shaman of the Throne admit with shame that the culprits are their own kin. With the blessing of the furies, the Earthen Ring sent living fire drawn from Incineratus himself to burn the village''s huts, a punishment meant to show the Lost Ones the fury of the elements.', 'quest 9805 description and completion text (Lost Ones banished to Zangarmarsh, spread filth, kin dredging waters to create marsh, living fire of Incineratus, Windyreed Village southeast of the Throne); DB spawns 3634: Windyreed Scavenger 17139, Windyreed Wretch 17141, hut quest credits; warcraft.wiki.gg/wiki/Lost_ones (devolved further than the Broken; Windyreed tribe in Nagrand)'),
(351808, 1, 3518, 8, 0, 0, 'Sunspring Post', 'Sunspring Post was a Mag''har fishing village on the shore of Lake Sunspring, the only holding the orcs of Garadar kept outside their walls. It fell to a raid by the Murkblood, a tribe of Broken who serve the bog lord Musel''ek of Coilfang. The orcs who lived there were slain or driven out, and the Murkblood dumped the bodies into the lake, threatening the water that Telaar also drinks. Now Murkblood raiders and putrifiers prowl the empty huts, bending the spirits of the air to their will and troubling the lake with their magic as they search for something hidden there. In the depths of the lake, a polluted essence shed by the water spirit Watoosun festers.', 'quest 9867 description (fishing village, kill or evict all orcs); quest 9863 description (only other territorial holding); quest 9862 description (Murkblood serve Musel''ek of Coilfang, sacked Sunspring, elemental magic); quest 9873 description (Musel''ek the bog lord); quest 9874 description (bodies dumped, primary source of water); quest 9862 completion text (searching for something); quest 9810 description (Watoosun''s Polluted Essence in Lake Sunspring)'),
(351809, 1, 3518, 9, 0, 0, 'The Ancestral Grounds', 'Far to the southwest of Garadar lie the Ancestral Grounds, where the Mag''har carry their dead to be laid among the honored spirits. It is the domain of Mother Kashur, who dwells there as a spirit and is seen only by those she allows to see her. The grounds were always a quiet, undisturbed place, but of late the ancestral spirits have risen in great agitation, wandering the hills in torment. A funeral procession bound here from Garadar never arrived: Warmaul ogres ambushed it on the road and desecrated the remains it carried. What troubles the spirits lies beyond these grounds, in the shadow of Oshu''gun.', 'quest 10081 description (Mother Kashur at the Ancestral Grounds, southwest); quest 10082 description (normally quiet and undisturbed, agitated spirits); DB spawns 3633: Agitated Orc Spirit 18043, Mother Kashur 18687; quests 9944, 9945 (funeral procession to the Ancestral Grounds ambushed by Warmaul, remains desecrated); quest 10101 (cause at Oshu''gun); quest 10081 (potion needed to speak with Kashur; a spirit is seen only if it allows it); warcraft.wiki.gg/wiki/Mother_Kashur (orc ghost)'),
(351810, 1, 3518, 10, 0, 0, 'Oshu''gun', 'Oshu''gun, the diamond mountain, towers over southwestern Nagrand, a vast crystal glittering above the plains. For the orcs it was the heart of their faith: every spring the clans gathered here for a great festival, and their shaman communed with the ancestors in its shadow, until the clans became a horde and the spirits fell silent. The mountain is not stone at all, but the wreck of the vessel that first carried the draenei to this world, and something of a naaru still lingers within. Its crystals draw covetous eyes. The Consortium wants to mine it, rogue ethereals are already prying fragments loose, and Shadow Council ritualists and Legion terrorguard have crept inside.', 'quest 10101 description (diamond mountain, springtime festival, shaman communed, clans became a horde, spirits silent); quest 10101 reward text (ship that first brought the draenei, K''ure); quest 9882 description (Consortium barred from Oshu''gun, Gava''xi''s rogue ethereals dislodging fragments); DB spawns 3630: Kil''sorrow Ritualist 18658, Terrorguard 18661, Vir''aani Raider/Arcanist; warcraft.wiki.gg/wiki/Oshu''gun (Kosh''harg, Shadow Council agents from Kil''sorrow)'),
(351811, 1, 3518, 11, 0, 0, 'The Spirit Fields', 'The Spirit Fields spread around the foot of Oshu''gun, and the name has never been more fitting. Ancient orc ancestors drift across the grass toward the mountain, murmuring of pain and a cold embrace, drawn by a pull they cannot resist. Voidspawn wander among them, creatures of the void that has grown within the mountain, and rogue ethereals of the Vir''aani pick at its fallen crystals. The land is perilous in other ways. The gronn Durn the Hungerer circles the fields hunting anything that moves, the great clefthoof Banthar leads her herd here, and strange distortions have begun to appear in the air, drawing the curious from as far as Shattrath.', 'DB spawns 3631: Ancient Orc Ancestor 18688, Voidspawn 17981, Vir''aani Arcanist/Raider, Gava''xi, Durn the Hungerer, Multiphase Disturbance; creature_text 18688 (ancestor lines); quest 10085 reward text (ancestors moving south); quest 10102 description (void minions drawn through the vortex); quest 9937 description (Durn lords over the Spirit Fields); quest 9851 (Banthar in the Field of Spirits); quest 11880 description (distortions in the Spirit Fields, Shattrath); creature 19475 Harbinger Haronem stands in Shattrath (quest 11880 giver)'),
(351812, 1, 3518, 12, 0, 0, 'Aeris Landing', 'North of Oshu''gun, the ethereal traders of the Consortium have set up camp at Aeris Landing. Their ground operations leader, Gezhe, spent months planning to mine Oshu''gun, which he calls the largest diamond known in the universe, only to be told by Nexus-Prince Haramad to wait until a political matter in Netherstorm was settled and not to anger the naaru. In the meantime Gezhe runs a clearing house for smuggled gems and pays well for ogre warbeads of obsidian. His security officer Zerid complains that the camp sits barely ten feet from crazed voidspawn, and the merchant Shadrek quietly buys elekk ivory, insisting it is not poaching.', 'npc_text 9287 (Gezhe: months of planning, largest known diamond in the universe, Haramaad, political matter in Netherstorm, clearing house for smuggled gems); quest 9882 description (might anger a naaru); quest 9913 description (Gezhe ground operations leader, Aeris Landing north of Oshu''gun); quest 9893 description (obsidian warbeads); quest 9925 description (Zerid, voidspawn ten feet away); quest 9914 description (Shadrek, not poaching)'),
(351813, 1, 3518, 13, 0, 0, 'Kil''sorrow Fortress', 'Kil''sorrow Fortress is a walled orc stronghold in southeastern Nagrand near the Terokkar border, named for the demon lord Kil''jaeden. Its masters, the Kil''sorrow, are agents of the Shadow Council who still commune with the Burning Legion. Cultists, spellbinders and deathsworn warriors patrol its walls alongside dark worgs, and its ritualists have spread to Oshu''gun. Garadar and Telaar both post bounties for Giselda the Crone and her lackeys, wanted for murder, ritual sacrifice, kidnapping, burglary and communing with the Legion. The Kil''sorrow have lately found themselves at war with the Warmaul ogres, thanks to a ruse by Lantresor of the Blade.', 'warcraft.wiki.gg/wiki/Kil''sorrow_Fortress (agents of the Shadow Council, named for Kil''jaeden, near Terokkar border); quest 9935/9936 description (Giselda''s crimes, bounties at Garadar and Telaar); DB spawns 3637: Kil''sorrow Deathsworn, Cultist, Spellbinder, Dark Worg 18033, Giselda 18391; Kil''sorrow Ritualist at Oshu''gun; quests 9927, 9931 (Lantresor''s ruse); npc_text 9369 (Lantresor: Shadow Council attacks)'),
(351814, 1, 3518, 14, 0, 0, 'Burning Blade Ruins', 'East of Telaar, near the Terokkar border, the Burning Blade Ruins hold the largest gathering of Boulderfist ogres in southern Nagrand. Great pyres burn on the upper levels of the compound, and on an upper platform waits the Boulderfist''s unlikely master, the old orc blademaster Lantresor of the Blade. The ogres have been driven here by the Warmaul, and they have struck back at their neighbors in turn: Bleeding Hollow orcs were driven from their village in a night attack, and the Kurenai fear an attack on Telaar. Mag''har battle standards now stand beside the pyres in answer, and the Kurenai once had to rescue Arechron''s son Corki from an ogre cage here.', 'quest 9921 description (largest collection of Boulderfist, east of Telaar near Terokkar); quest 9910 description (flaming pyres on upper levels, Mag''har battle standards); quests 10107/10108 (Lantresor on an upper platform, blademaster); quest 9890 description (Warmaul pushing Boulderfist); quest 9888 description (attack on Jorin''s village); quest 9921 description (precursor to invasion of Telaar); quest 9923/9924 (Corki rescued from the Burning Blade Ruins); DB spawns 3610'),
(351815, 1, 3518, 15, 0, 0, 'Laughing Skull Ruins', 'Against the northern mountains of Nagrand lie the Laughing Skull Ruins, one of the old villages of the orc ancestors. The Warmaul ogres have overrun it and built an ogre mound among its broken walls. From here Zorbo the Advisor and his reavers and shaman planned attack after attack on Garadar and Telaar, slaying orcs and Broken alike, and both towns pay for proof of his death. A blazing pyre lights the ruins'' courtyard, where the bodies of Kil''sorrow orcs were laid out to start a war. The most famous corner of the ruins, though, is the Ring of Blood, where the goblin Gurgthock stages fights for the ogres'' amusement.', 'quests 9939/9940 descriptions (Zorbo, reavers and shaman, Laughing Skull Ruins in the northern mountains, attacks on Garadar and Telaar); quest 10085 description (Laughing Skull Ruins among the villages of the ancestors); warcraft.wiki.gg/wiki/Laughing_Skull_Ruins (overrun by Warmaul, ogre mound, Ring of Blood); quest 9932 description (pyre in the courtyard, bodies); npc_text 9735 (Gurgthock runs the Ring of Blood at the old Laughing Skull Ruins)'),
(351816, 1, 3518, 16, 0, 0, 'Warmaul Hill', 'In the northwestern mountains of Nagrand stands Warmaul Hill, stronghold of the Warmaul ogres. Its great cave once belonged to the gronn who ruled these ogres, until Cho''war the Pillager drove them out and named himself king. The Warmaul are cruel even by ogre standards. They keep captured Mag''har in cages to be eaten fresh, their chef stirs a bubbling stew and boasts of his Broken chowder, and they hoard supplies stolen from a Kurenai caravan. Somewhere on the hill the ogres worship a traitor earth spirit, Gurok, at a brand of stone, and mountain gronn still roam the slopes.', 'quest 9946 description (Cho''war forced the gronn out of the cave, declared himself king); quest 9948 description (prisoners kept alive for food); creature_text 18440 (Warmaul Chef Bufferlo: stew, Broken chowder); quest 9956 description (caravan supplies stolen); quest 9853 description (ogre worships Gurok, earthen brand at Warmaul Hill); DB spawns 3617: Mag''har Prisoner, Warmaul Prison, Mountain Gronn 19201, Telaar Supply Crate'),
(351817, 1, 3518, 17, 0, 0, 'The Forge Camps', 'In the far west of Nagrand the Burning Legion has raised two forge camps, Hate and Fear, to build weapons for its war on this land. Each camp has a forge, spell warding towers and a transporter linking it to the Legion''s armies, and as long as the transporters stand nothing done to the camps will last. Mo''arg engineers and tinkerers labor beneath the watch of felguard and the fel cannons of the camp defenses. A mo''arg master planner keeps the blueprints that decide where every structure goes, and each camp is ruled by a pit lord overseer, Demos at Hate and Xirkos at Fear, so dangerous that Altruis warns any who would face them to bring allies.', 'npc_text 9427 (Altruis: two forge camps, transporter, forge, warding towers, fel cannons, pit lord overseers); quest 9999 description (transporters, engineers and tinkerers); quest 10001 description (master planner and blueprints); DB spawns 3624/3625: Demos, Overseer of Hate 18535; Xirkos, Overseer of Fear 18536; Mo''arg Master Planner; Gan''arg Tinkerer; Mo''arg Engineer; Felguard Legionnaire; Legion Fel Cannon; warcraft.wiki.gg/wiki/Altruis_the_Sufferer (weapons in western Nagrand)'),
(351818, 1, 3518, 18, 0, 0, 'Nesingwary Safari', 'On the northeastern edge of Nagrand, near the border of Zangarmarsh, the famous dwarf hunter Hemet Nesingwary has pitched his camp. He came to Outland in search of real big game, and he has the scars to prove he found it. With him are Shado Farstrider, a quiet hunter who earned the nickname Fitz by losing a wager to Hemet over a frostsaber in Winterspring, and Harold Lane, who insists that the infected scratch he got brawling with a talbuk stag and a pair of windrocs is nothing. Their pilot, Marsha, is patching up the flying machine that crashed because Hemet shot through its ailerons. A copy of Hemet''s book, The Green Hills of Stranglethorn, lies in the camp.', 'quest 10113 log description (outskirts of northeast Nagrand, towards Zangarmarsh); npc_text 9221 (Hemet: prey in Outland the real deal, scars); npc_text 9283 (Fitz: Winterspring, Rak''shiri wager, nickname); npc_text 9258 (Harold Lane scratch); npc_text 9290 (Pilot Marsha, ailerons); gameobject 182203 The Green Hills of Stranglethorn in area 3673; quest 10114 description (expedition came from Azeroth)'),
(351819, 1, 3518, 19, 0, 0, 'The Ring of Trials', 'The Ring of Trials is the great arena of Nagrand, and the old battlemaster Garokk remembers when it was a place of great glory and honor. Then the Steamwheedle Cartel arrived with wagons of gold and pens sharper than any axe. The goblins took the arena over and renamed it Steamwheedle Stadium, and it now hosts the bouts of the Steamwheedle Fighting Circuit. The organizer King Dond sells the charters that would-be gladiators need, while the brute Ear-Biter turns away anyone he judges unworthy of the ring. Garokk lingers nearby, a battlemaster without a battle.', 'npc_text 9637 (Garokk: once a place of great glory and honor, Steamwheedle came with gold and quill pens); creature_text 18897 (recently appropriated and callously renamed Steamwheedle Stadium); npc_text 10608 (King Dond sells arena team charters, Steamwheedle Fighting Circuit); npc_text 10214/10215 (Ear-Biter); creature_template 18439 subname Ex-Arena Battlemaster; warcraft.wiki.gg/wiki/Nagrand (Ring of Trials, the zone''s arena)'),
(351820, 1, 3518, 20, 0, 0, 'The Twilight Ridge', 'High on the Twilight Ridge of western Nagrand, reached only on wings, stands a dimensional gateway through which the Burning Legion once brought demons into this world. The gateway is dark now, but not forgotten. Deathshadow cultists have built a camp around it, and Shadow Council spellcasters channel magic into its frame in an effort to stabilize it and open the way again. They are overseen by the eredar Reth''hedron the Subduer, whose own brother, Balthas, is a lord in Illidan''s service. Illidan''s forces strike at the ridge whenever they can, determined that the portal stay closed.', 'warcraft.wiki.gg/wiki/Twilight_Ridge (Legion dimensional gateway no longer functional, Deathshadow cultists, Reth''hedron, Shadow Council channeling into the frame, flying only); quest 11086 description (demons attempt to stabilize the portal on the Twilight Ridge; Dragonmaw silencing those who defy Illidan); quest 11090 description (Reth''hedron, brother of Illidari Lord Balthas); DB spawns 3764: Deathshadow Spellbinder/Warlock/Archon/Acolyte/Overlord, Reth''hedron the Subduer 22357'),
(351821, 1, 3518, 21, 0, 0, 'The Abandoned Armory', 'North of Telaar stands the Abandoned Armory, an old draenei building where Boulderfist ogres now stack stolen Bleeding Hollow supplies. One resident is not an ogre. The draenei Nitrin the Learned lives here with a grief he cannot shake. His son Levixus was seduced by demons who offered him power, then gave him a taste of it, and the young draenei made off with a book of the dead bought from Shattrath''s ruffians. Nitrin, who knows the rites of Auchindoun''s death priests, warns that the boy now means to bind the souls of that great tomb to his will, and he begs any stranger with a conscience to stop him.', 'quest 10251 description and reward text (Abandoned Armory north of Telaar, Levixus communing with demons, book taken); quest 10252 description and reward text (Levixus raising Auchindoun''s dead, death priest rite); DB spawns 3839: Nitrin the Learned 19844, Boulderfist Mage/Warrior, Bleeding Hollow Supply Crate'),
(351822, 2, 3518, 1, 2, 0, 'Greatmother Geyah', 'Greatmother Geyah is the venerable matriarch and spiritual leader of the Mag''har. She is the widow of the Frostwolf chieftain Garad and the mother of Durotan, who left Draenor long ago with his mate Draka and never returned. In a very real sense she raised every orc in Garadar, and the town''s matrons dread the day she passes. That day seems close: she has fallen gravely ill and keeps to the hospice, while the clan''s young war chief sinks into despair. Yet her mind is sharp, and she still guides those who would help her people. She has heard nothing of her son since he left, nor of the child Draka was carrying.', 'warcraft.wiki.gg/wiki/Garadar (spiritual leader, Durotan''s mother, hospice); creature_text 18141 (Draka with child before leaving, Durotan); creature_text 18489 (Garad and Geyah); npc_text 9297 (Matron Drakia: the Greatmother raised all of us); quest 9944 description (Greatmother taken ill); quest 9868 reward text (Greatmother is dying)'),
(351823, 2, 3518, 2, 2, 0, 'Garrosh', 'Garrosh, son of Grommash Hellscream, is the young war chief of the Mag''har and heir to lead them when the Greatmother passes. He carries that duty like a curse. All his life he has heard that his father was the first orc to drink the demon''s blood and bring damnation on their people, and he believes that same taint runs in his veins. With Geyah dying and enemies on every side, he sits by the fire in Garadar, unmoved by victories and deaf to calls for action, while Jorin Deadeye openly calls him an impotent whelp. He fears above all becoming the second Hellscream to doom the orcs, and he would rather die than lead.', 'creature_template 18063 subname Son of Hellscream; warcraft.wiki.gg/wiki/Mag''har (military chief, to succeed Geyah); creature_text 18141 (Grom first to drink from the chalice, the only truth Garrosh has known); quests 9868, 9872, 9934 reward texts (depressed, dismissive); quest 9891 reward text (Jorin: impotent whelp); quest 10171 reward and 10172 description (would rather die, second Hellscream)'),
(351824, 2, 3518, 3, 2, 0, 'Jorin Deadeye', 'Jorin Deadeye, son of Kilrogg, calls himself the last of the line of Deadeye, warchiefs of the Bleeding Hollow clan, and he names the Mag''har proudly as survivors: of a fallen dynasty, of the red pox and of a shattered world. When Boulderfist ogres fell on his village by night and drove his people out, he escaped to Garadar and found its leader weeping into a fire. Jorin has little patience for that. He believes ogres respect only might and sends every willing warrior to teach them so, yet he is shrewd as well as fierce, for when he learned that an old orc commanded the Boulderfist, he chose to send an envoy before an army.', 'npc_text 9289 (son of Kilrogg, last of the lineage of Deadeye, survivors); quest 9888 description (village attacked at night, Garrosh weeping into a fire); quest 9906 description (ogres moved by might); quest 10107 description (Diplomatic Measures); warcraft.wiki.gg/wiki/Garadar (aide to Garrosh)'),
(351825, 2, 3518, 4, 2, 0, 'Saurfang the Younger', 'Saurfang the Younger was one of the Garadar younglings who could bear no more after yet another Murkblood raid and set out to strike back, though their elders tried to stop them. The war party, barely grown, took the western road to Sunspring Post and was cut to pieces. Alone left alive, he tells of a rage that burned through his whole being as thirty Murkblood closed around him, and of waking later with no memory of the fight, eyes still flashing red. Nearly dead, he was found by the survivors of a funeral procession. He refused to return home, sure his destiny lay elsewhere, and in time he left Nagrand to join his father, Varok Saurfang, in the Horde.', 'quest 9864 description (younglings, rage, western road); npc_text 9275 (the rage, thirty Murkblood, blacked out, eyes glow red); quest 9944 reward text (found nearly dead near Sunspring); quest 9866 description and reward text (will not return, destiny elsewhere; the son is the father); warcraft.wiki.gg/wiki/Dranosh_Saurfang (son of Varok, later traveled to Azeroth and reunited with his father); creature_text 37187 (3.3.5 Icecrown: High Overlord Saurfang''s son kept safe and untainted beyond the Dark Portal); creature 25257 Saurfang the Younger in Northrend (3.3.5)'),
(351826, 2, 3518, 5, 1, 0, 'Arechron', 'Arechron leads the Kurenai of Telaar, and he carries the weight of his people with a weary dignity. He knows his enemies personally: when Murkblood invasion plans reached him, he recognized the hand of Ortor, once a noble Broken versed in the elements, now a muck-addled servant of the bog lord. He also guards a secret about the totem of Kar''dash, which only the chosen may learn. His greatest trial, though, is his son Corki, whose curiosity has got him caught by the Boulderfist twice and then by the Warmaul, who threatened to cook him in a stew. After the third rescue, Arechron sent the boy off to live among the night elves of Blade''s Edge.', 'warcraft.wiki.gg/wiki/Kurenai (main leader Arechron); quest 9873 description (Ortor once a noble Broken, yes-man of Musel''ek); quest 9879 reward text (only the chosen may know); quests 9923, 9924, 9954, 9955 (Corki captured at Burning Blade Ruins, Halaani Basin, Warmaul Hill; sent to night elves in Blade''s Edge); creature_text 18440 (put in da Corki); creature_text 18445 (saved three times)'),
(351827, 2, 3518, 6, 0, 0, 'Lantresor of the Blade', 'Lantresor of the Blade is an orc blademaster who crossed the Dark Portal with the Horde in the days of the first invasions and has since come home to Draenor. In the absence of their missing chieftain Krol, he now rules the Boulderfist ogres from an upper platform of the Burning Blade Ruins. He greets strangers by asking whether they know death when they see it, and he is as cunning as he is deadly. Pressed by the Warmaul from the north and harried by orcs and Kurenai alike, he offered envoys of both towns a bargain: help him turn his enemies against one another, and his ogres would leave their people in peace.', 'quests 10107/10108 descriptions (ancient orc who passed through the Dark Portal in the time of our fathers, returned, blademaster, upper platform); quest 9890 description (Krol missing, Lantresor rules); npc_text 9361 (do you not know death by sight); npc_text 9369 (plan; Boulderfist territory back, peace); warcraft.wiki.gg/wiki/Lantresor_of_the_Blade'),
(351828, 2, 3518, 7, 0, 0, 'Altruis the Sufferer', 'Altruis the Sufferer is a night elf demon hunter who came to Outland in Illidan''s service and left it. He still honors Illidan for setting him on his path, but believes his old master has become the very thing he swore to fight, and he counts the Illidari as foul as any demon. He arrived in Nagrand on the back of his nether drake, Nethrandamus, asking questions in Garadar and Telaar and leaving word that any who sought a purpose should find him. His camp in the west looks out over the Legion''s forge camps. His name is feared in the Legion''s fields, and the Aldor and the Scryers send their agents to him for knowledge of Illidan''s demon hunters.', 'quest 10668 description (respect for Illidan, corrupted, Illidari an abomination); quests 9982/9983 descriptions (arrived on a nether drake, asked questions, seek a purpose); quest 9991 description (Nethrandamus); npc_text 9419 (what do you see when you look to the west); quests 10640/10689 descriptions (name feared in the Legion fields of Nagrand, Aldor and Scryers); warcraft.wiki.gg/wiki/Altruis_the_Sufferer (night elf, brought to Outland by Illidan, defected)'),
(351829, 2, 3518, 8, 0, 0, 'K''ure', 'Deep within Oshu''gun dwells K''ure, a naaru whose voice is a gentle melody in the mind. The diamond mountain is his ancient vessel, the ship that first brought the draenei to this world, which fell from the heavens and crashed here many hundreds of years ago. His weakened energies have been trapped in the wreckage ever since. As his Light bled away over the centuries, a void grew in its place and began to devour nearby souls, and generations of orc spirits have been drawn helplessly into it. He admits that he is the source of the ancestors'' pain. Worse, the Burning Legion has learned to use the vortex to summon void creatures for its armies.', 'quest 10101 reward text (K''ure of the naaru, ancient vessel, ship that first brought the draenei, crashed many hundreds of years ago, source of the orc spirits'' pain); quest 10102 description (energies bled away, void growing, devouring souls, Legion harnessed the vortex for void minions); DB spawn: K''ure 17545 in area 3631 by Oshu''gun'),
(351830, 2, 3518, 9, 0, 0, 'Cho''war the Pillager', 'Cho''war the Pillager is the self-made king of the Warmaul ogres. Few have seen an ogre king and lived to tell of it, but the tale of his rise is told across Nagrand: the ogres of the hills once served the gronn, until Cho''war drove the gronn out of their cave on Warmaul Hill, declared himself king and dissolved the old clans. From those pieces the Warmaul were born. Under him the ogres have seized much of the Boulderfist''s land, ambushed a Mag''har funeral procession, and taken captives from Garadar and Telaar alike. He keeps to the deepest caves of Warmaul Hill, heavily guarded, with the key to Corki''s cage on his person.', 'quest 9946 description (ogre king, forced the gronn out of the cave, dissolved the clans, Warmaul born, deep in the caves); quest 9946 completion text (heavily guarded); quest 9890 description (Warmaul took most Boulderfist land); quest 9945 description (ambush on the procession); quest 9955 and 9954 reward text (Cho''war has the key); DB spawn 18423 at Warmaul Hill'),
(351831, 2, 3518, 10, 0, 0, 'Durn the Hungerer', 'Durn the Hungerer is a gronn, one of the sons of Gruul, the great gronn lord whose lair lies in the Blade''s Edge Mountains. Durn has claimed the Spirit Fields around Oshu''gun as his hunting ground, and he circles the mountain without rest, destroying everything in his path. No hunter has yet managed to bring him down, and both Garadar and Telaar have put a price on his head, the last and greatest of their wanted posters. Those who take up the hunt are urged to bring their allies, for the gronn is huge and merciless.', 'creature_template 18411 subname Son of Gruul; warcraft.wiki.gg/wiki/Durn_the_Hungerer (one of the seven sons of Gruul, circles the Spirit Fields); quests 9937/9938 descriptions (lords over the area around Oshu''gun, decimating all, none able to rid Nagrand of him, gather allies); warcraft.wiki.gg/wiki/Gruul (Gruul''s Lair in Blade''s Edge, ogre overlord)'),
(351832, 3, 3518, 1, 0, 0, 'The Fall of Sunspring Post', 'When the Murkblood Broken sacked Sunspring Post, slaying or driving out every orc who lived there, both of Nagrand''s towns felt the blow. In Garadar, the farseers of the Lightning Sons refused to sit idle while their chieftain grieved: one sought the Murkblood''s idols, another their leader''s head, to mount on a pike by the gates. In Telaar, the Kurenai feared for the lake. Otonbu the Sage had the rotting bodies of the dead burned before they could poison the water, knowing the orcs would never understand, and Poli''lukluk sent fighters to thin the raiders, for all an orc sees is Broken. Invasion plans pointed to Ortor of Murkblood, once a friend of Arechron, and to attacks on both towns, while the Earthen Ring found the raiders enslaving spirits of the air. Rescued captives revealed what the Murkblood truly sought: the lost totem of Kar''dash.', 'quests 9863, 9867 (Lightning Sons farseers, idols, leader''s head on a pike); quests 9874 description and reward text (Otonbu, corpses, peace set back); quest 9878 description (Poli''lukluk, all an orc sees is Broken); quests 9871, 9872, 9873 (invasion plans, Ortor); quest 9862 (Morgh, putrifiers capture air spirits); quests 9868, 9879 (captives, totem of Kar''dash); creature_template 18066 subname The Lightning Sons'),
(351833, 3, 3518, 2, 2, 0, 'The Missing Procession', 'Though the Greatmother lay ill, she insisted that life go on, and so a funeral procession of thirty Mag''har set out from Garadar for the Ancestral Grounds. It never arrived. Matron Drakia sent a stranger down the western road, and only two elders were found alive, Yorley and Ungriz. Warmaul ogres had fallen on the procession from all sides, slaughtering guards and mourners and desecrating the remains of the elder they were carrying, purely to show their power. Even the gentle Yorley wanted vengeance. The killers were hunted down on Warmaul Hill, and their king, Cho''war the Pillager, was slain in his cave, his head posted at Garadar''s gates. Ungriz, knowing ogres like their food fresh, had the captives sought out in their cages and brought home alive.', 'quest 9944 description and reward text (Greatmother says life goes on, procession to the Ancestral Grounds, thirty orcs, only Ungriz and Yorley remain); quest 9945 description (ambush, desecrated remains, spiritual orc''s limits); quest 9946 description and reward text (Cho''war, head posted at the gates); quest 9948 description (food fresh, free prisoners); creature_queststarter: 9944 from Matron Drakia 18302'),
(351834, 3, 3518, 3, 0, 0, 'Lantresor''s Gambit', 'The Boulderfist ogres were on the move. Jorin Deadeye of Garadar sent help to his scout Kilrath, hiding by the ruined Bleeding Hollow village over the Terokkar border, and on Kilrath''s plan the ogre Unkor was beaten until he talked: the Warmaul were driving the Boulderfist from their lands, their chieftain Krol had vanished, and an orc called Lantresor ruled in his place. In Telaar, the huntress Bintook found ogre war plans and squeezed the rest from a lieutenant named Lump. Both towns answered with blood at the Burning Blade Ruins and the twin clefts, then sent an envoy to Lantresor himself. The old blademaster proposed a bargain. Warmaul banners were driven into slain Kil''sorrow orcs, Kil''sorrow banners into slain Warmaul ogres, and Kil''sorrow bodies were heaped in the Laughing Skull Courtyard at a smoke signal. With the two enemies at each other''s throats, Lantresor sent a peace offering home with the envoy. Arechron accepted it gladly. Garrosh kicked the crate aside.', 'quests 9888-9891 (Kilrath, Unkor, Krol missing, Lantresor rules); quests 9917, 9918, 9920 (Bintook, Lump); quests 9906, 9907, 9921, 9922 (Burning Blade Ruins, twin clefts); quests 10107, 10108 (Diplomatic Measures); quests 9927, 9928, 9931, 9932 (banners and bodies, smoke signal); quests 9933, 9934 reward texts (Arechron, Garrosh kicks the crate aside)'),
(351835, 3, 3518, 4, 0, 0, 'Gurok the Usurper', 'At the Throne of the Elements, Elementalist Untrag felt something pounding beneath the earth, endlessly, as if punishing it, and sent a stranger to hear the earth fury Gordawg. Gordawg, who speaks little and chews rocks to learn where they have been, set the stranger to lay the tortured earth spirits of the Telaari Basin back to sleep. Then he tasted the cores of raging crushers and spat them out: poison, not Nagrand. With a boulder broken from his own back, the stranger shattered the shells of the poison rock''s minions at the southwestern edge of the world and brought back a name. Gurok, an earth spirit who had betrayed the elements, was being worshipped by the Warmaul ogres. Seven ogre skulls laid on his brand at Warmaul Hill drew him out to be destroyed, and Gordawg crushed his head between his jaws.', 'quest 9818 description (Untrag, beating underneath, listen to Gordawg); quest 9819 description (tortured earth spirits, Telaari Basin); quest 9821 description and reward text (chews rock, poison rocks not Nagrand); quest 9849 description and reward text (boulder from his back, edge of the world southwest, Gurok betrayed the elements); quest 9853 description and reward text (Warmaul worship Gurok, seven skulls, earthen brand, Gordawg crushes head)'),
(351836, 3, 3518, 5, 0, 0, 'The Polluted Waters', 'Elementalist Lo''ap of the Earthen Ring could see that Nagrand''s waters were sick. Before sending anyone into them, he prepared tablets from a rare bean, picked from the dung of the plains'' beasts, that let a body breathe water. The maddened spirits of Skysong Lake came first, put down with the permission of Watoosun of the Water. The source of the trouble proved to be the Lost Ones of Windyreed Village, dredging the lakes into marsh, and with the blessing of Incineratus their huts were burned with living fire. Yet more trouble surfaced. In shedding its corruption, Watoosun had cast off a twisted essence of pure filth that now lurked in Lake Sunspring, breeding foul offspring, and it too had to be destroyed. Beneath Halaa, spawns of muck were slain and their tainted cores carried away so that the poison could spread no further.', 'quest 9800 description and reward text (caracoli bean from dung, tablet to breathe water); quest 9804 description (Skysong lake spirits, Watoosun''s permission); quest 9805 description and texts (Lost Ones of Windyreed, living fire of Incineratus); quest 9810 description (Watoosun''s polluted essence in Lake Sunspring, corrupt offspring); quest 9815 description (muck spawns in Halaani Basin, cores)'),
(351837, 3, 3518, 6, 0, 0, 'The Ring of Blood', 'In the Laughing Skull Ruins the Warmaul ogres keep a fighting pit, the Ring of Blood, and the goblin Gurgthock runs its bouts, with his troll servant Wodin at hand. The rules are simple: the fight ends when one side lies dead on the arena floor. Challengers face a ferocious clefthoof called Brokentoe, then the Murkblood twins known as the Blue Brothers, then Rokdar the Sundered Lord, a giant of living rock hauled from Blade''s Edge, then Skra''gath, a creature of air and shadow. Next comes the Warmaul champion, shipped in from the gladiator pits of Blade''s Edge, where he trained against mountain giants three at a time. Then Mogor, hero of the Warmaul, who has watched every fight while the ogres'' bets climbed, invokes his right of battle for the first time in the ring''s history. Gurgthock, of course, bets the house on the challenger.', 'quests 9962, 9967, 9970, 9972, 9973, 9977 (descriptions and reward texts); creature_text 18471 (Gurgthock announcements, first time Mogor exercised his right of battle); creature_text 18069 (Mogor: Skra''gath made of air and shadow); npc_text 9735 (Gurgthock runs the show at the old Laughing Skull Ruins); quest_template 9962 ender Wodin the Troll-Servant 22893'),
(351838, 3, 3518, 7, 0, 0, 'Altruis and the Forge Camps', 'When Altruis the Sufferer arrived in western Nagrand, he left word in Garadar and Telaar that any who sought a purpose should come to him. The Legion''s wards hid the camps from his sight, so he sent his volunteers soaring over the forge camps on his nether drake to note every tower and transporter. Slowing the camps'' engineers bought him time, but fel steel could not be destroyed by ordinary means. Altruis wanted the camps'' blueprints, stolen from their mo''arg master planner, and he sent them to an old acquaintance in the Lower City of Shattrath: Sal''salabim, a drunken mo''arg who had once designed such camps himself. After some persuading, and a few debts collected, Sal''salabim laughed and gave his answer. Turn the camps'' own fel cannons around. The catch was that only the pit lord overseers held the keys. They fell, and the cannons turned on the camps of Hate and Fear.', 'quests 9982/9983 descriptions; quest 9991 description (catalog the camps on Nethrandamus); quest 9999 description and reward text (transporters, buying time, no conventional means of destroying fel steel); quest 10001 description and reward text (master planner''s blueprints, acquaintance was a Legion engineer); quest 10004 description (Sal''salabim in the Lower City, at the bar); quests 10009, 10010 (debts, ''This Sal''salabim design'', turn the cannons, overseers have keys); quest 10011'),
(351839, 3, 3518, 8, 2, 0, 'The Restless Ancestors', 'Sent for by the Greatmother through a grudging Garrosh, a stranger came before Greatmother Geyah, who sent them out across Outland for four herbs and brewed a potion so that they might speak with Mother Kashur at the Ancestral Grounds. The potion, Kashur later admitted, did nothing; it was a test of belief. The ancestors there had risen in torment, and when the stranger visited the old villages of the ancestors, Sunspring, the Laughing Skull Ruins, Garadar and the Bleeding Hollow, no spirits were at home. All were drifting south. Kashur sent the stranger to Oshu''gun, where the naaru K''ure revealed the truth: the void growing in his failing vessel was swallowing orc souls. On his advice the stranger went to A''dal in Shattrath and then into the Auchenai Crypts, where the spirit of another naaru, D''ore, explained that the cycle could not be stopped, only eased. Using soul mirrors, the stranger freed the ancient spirits before the void could claim them.', 'quest 10044 description (Garrosh delivers the summons); quest 10045 description (four herbs from four lands, potion); quest 10081 description and reward text (potion has no real effect, a test); quests 10082, 10085 and 10085 reward text (agitated ancestors, villages visited, spirits moving south); quests 10101, 10102 (K''ure, void devouring souls, A''dal); quests 10167, 10168 (Auchenai Crypts, D''ore, cycle cannot be stopped, soul mirrors, darkened spirits)'),
(351840, 3, 3518, 9, 2, 0, 'Hero of the Mag''har', 'When the stranger brought word that the ancestors could rest, the Greatmother sent them to tell Garrosh, hoping the news would lift him. It did not. Garrosh admitted that his people were proud, but asked what lay beyond another winter, offered to let the stranger lead the clan instead, and declared that he would never become the second Hellscream to damn the orcs. In tears, Geyah sent the stranger across the Dark Portal to Orgrimmar with a message for the Warchief: his blood lived on in Outland. Thrall came to Garadar bearing the Doomhammer. Geyah knew him at once by his father''s shoulders and his mother''s eyes, and gave him the name Durotan had chosen for his son: Go''el. Then she asked him to tell Garrosh the truth of how Grom Hellscream died. Hearing it, Garrosh was freed at last, and proclaimed himself son of Grom and chieftain of the Mag''har.', 'quest 10170 reward text, 10171 description and reward text (Garrosh, another winter, lead the clan); quest 10172 description and reward text (second Hellscream, seek out your warchief); quest 10175 description and reward text (Thrall: I have a grandmother?); creature_text 18141 (Geyah recognises Thrall, Go''el, asks him to tell Garrosh); creature_text 18063 (Garrosh: redemption, son of Grom, chieftain of the Mag''har); creature_text 18489 (He carries the Doomhammer)'),
(351841, 3, 3518, 10, 0, 0, 'The Nagrand Safari', 'Hemet Nesingwary does not let just anyone hunt with his expedition, and in Nagrand the tests are harder than ever. Hemet starts his recruits on the clefthoof near camp, then the far more dangerous bulls, and finally Banthar, the fiercest and hairiest clefthoof in Outland, who roams with her herd near Oshu''gun. Fitz Farstrider, who speaks of honoring the last heartbeats of fallen prey, leads hunters through ever deadlier windrocs to their mother, Gutripper, far to the west. Harold Lane, too sick from his scratch to hunt, sends others after talbuk stags, thorngrazers and Bach''lor, king of the stags. Those who master all three may face the queen of Nagrand: Tusker, a giant elekk who stands on a great bluff above Oshu''gun. Hemet offers, only half in jest, to send a letter to the next of kin.', 'quests 9789, 9850, 9851 (clefthoof, bulls, Banthar fiercest and hairiest, Field of Spirits near Oshu''gun); quests 9854, 9855, 9856 (Fitz, last heartbeats, Gutripper mother of windrocs, far west); quests 9857, 9858, 9859 (Harold Lane, stags, thorngrazers, Bach''lor king of the stags); quest 9852 description (Tusker, queen, bluff overlooking Oshu''gun, letter to next of kin)');
